def sort_products(products):
    result = list(products)
    n = len(result)

    for i in range(n - 1):
        best = i
        for j in range(i + 1, n):
            left = result[j]
            right = result[best]
            better = left['price'] > right['price']
            if left['price'] == right['price'] and left['name'] < right['name']:
                better = True
            if better:
                best = j

        if best != i:
            result[i], result[best] = result[best], result[i]

    return result

def first_unique_char(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    for index, ch in enumerate(text):
        if counts[ch] == 1:
            return index
    return -1

def move_zeros(nums):
    result = [n for n in nums if n != 0]
    return result + [0] * (len(nums) - len(result))
